In ios/Podfile, make the following changes:Add the following lines just below the require block for React Native:require Pod::Executable.execute_command('node', ['-p',
  'require.resolve(
    "@capillary/react-native-hydra-lib/scripts/HydraPods.rb",
    {paths: [process.argv[1]]},
  )', __dir__]).stripAdd the following lines just below the config = use_native_modules!, in your main target:hydra_podsGo to the terminal, navigate to the ios folder of your project, and run pod install.Add GoogleServices-Info.plist to your iOS project using Xcode.Copy HydraConfig.plist from the template folder of the cloned main branch.  Then, add it to your iOS project using Xcode. You can also change the values in the .plist file as needed.Configure the initialiser for your Content Management System (CMS) tool. In your AppDelegate.mm, you need to initialise the Hydra SDK.For Firebase Remote configuration:Add the import statement at the top of your file:#import <react-native-hydra-lib/HydraNativeInitializer.h>import react_native_hydra_libNavigate to the following functions:- (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NSDictionary *)launchOptionsfunc application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey : Any]? = nil) -> BoolReplace the following return statements:return [super application:application didFinishLaunchingWithOptions:launchOptions];

// Replace the above with:

BOOL result = [super application:application didFinishLaunchingWithOptions:launchOptions];
[[HydraNativeInitializer sharedInstance] initApplicationUsingFirebaseRemoteConfig:application 
                                                    didFinishLaunchingWithOptions:launchOptions];

return result;return super.application(application, didFinishLaunchingWithOptions: launchOptions)

// Replace the above with:

let result = super.application(application, didFinishLaunchingWithOptions: launchOptions)
HydraNativeInitializer.sharedInstance().initApplication(
    usingFirebaseRemoteConfig: application,
    didFinishLaunchingWithOptions: launchOptions
)

return resultFor other CMS tools:Add the import statement at the top of your file:#import <react-native-hydra-lib/HydraNativeInitializer.h>
#import <react-native-hydra-lib/HydraNativeRemoteConfig.h>import react_native_hydra_libNavigate to the following functions:- (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NSDictionary *)launchOptionsfunc application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey : Any]? = nil) -> BoolReplace the following return statements:return [super application:application didFinishLaunchingWithOptions:launchOptions];

//Replace the above with:
BOOL result = [super application:application didFinishLaunchingWithOptions:launchOptions];
HydraNativeRemoteConfig *remoteConfig = [[HydraNativeRemoteConfig alloc]
                                          initWithAccountId:@"<YOUR_ACCOUNT_ID>"
                                          baseUrl:@"<YOUR_BASE_URL>"
                                          sslPublicKey:@"<YOUR_SSL_PUBLIC_KEY>"
                                          remoteLogLevel:0];
[[HydraNativeInitializer sharedInstance] initApplication:application didFinishLaunchingWithOptions:launchOptions withHydraRemoteConfig:remoteConfig];
return result;return super.application(application, didFinishLaunchingWithOptions: launchOptions)

//Replace the above with:
let result = super.application(application, didFinishLaunchingWithOptions: launchOptions)
let remoteConfig = HydraNativeRemoteConfig(accountId: "<YOUR_ACCOUNT_ID>", baseUrl: "<YOUR_END_POINT>", sslPublicKey: "<YOUR_SSL_KEY>", remoteLogLevel: 0)
HydraNativeInitializer.sharedInstance().initApplication(application, didFinishLaunchingWithOptions: launchOptions, withHydraRemoteConfig: remoteConfig)
return result

In android/app/build.gradle, add the following lines at the bottom of the file:apply from: file("../../node_modules/@capillary/react-native-hydra-lib/scripts/hydra_github_setup.gradle")Add google-services.json to the android/app folder.Copy hydra-config.json from the template folder of the cloned main branch. Paste it into the android/app/src/main/assets folder. You can also change the values in the .json file as needed.In your MainApplication file, you need to initialise the Hydra SDK. Add the following import statements at the top of your file:import com.hydralib.nativeapis.HydraInitializer
import com.hydralib.nativeapis.HydraRemoteConfigimport com.hydralib.nativeapis.HydraInitializer;
import com.hydralib.nativeapis.HydraRemoteConfig;Configure the initialiser for your Content Management System (CMS) tool.For Firebase Remote configuration:Use the following methods to get the Account ID, SSL Public Key, Base URL, and Remote Log Level from Firebase Remote Config. Add the following code to the onCreate function, immediately after the default React Native generated code:HydraInitializer.initializeUsingFirebaseRemoteConfig(this)HydraInitializer.initializeUsingFirebaseRemoteConfig(this);For other CMS tools:Use the following methods to get the Account ID, SSL Public Key, Base URL, and Remote Log Level from your CMS. Add the following code to the onCreate function, immediately after the default React Native generated code:val accountId = "your_account_id"
val baseURL = "your_base_url"
val sslPublicKey = "your_ssl_public_key"
val remoteDebugLevel = 0 // For example, 0 for no logs, adjust as needed

HydraRemoteConfig.Builder(
    accountId, baseURL, sslPublicKey, remoteDebugLevel
).build().let { remoteConfig ->
    HydraInitializer.initialize(this, remoteConfig)
}String accountId = "your_account_id";
String baseURL = "your_base_url";
String sslPublicKey = "your_ssl_public_key";
int remoteDebugLevel = 0; // For example, 0 for no logs, adjust as needed

HydraRemoteConfig remoteConfig = new HydraRemoteConfig.Builder(accountId, baseURL, sslPublicKey, remoteDebugLevel)
        .build();

HydraInitializer.initialize(this, remoteConfig);
